/* IST professional factory layout editor.
 * Business data stays renderer independent; Fabric.js is the viewport adapter.
 */
const PRO_LAYOUT_SCHEMA=1,PRO_LAYER_DEFAULTS=[
 {id:'building',name:'Building',visible:true,locked:false},
 {id:'production',name:'Production Line',visible:true,locked:false},
 {id:'equipment',name:'Equipment',visible:true,locked:false},
 {id:'process',name:'Process',visible:true,locked:false},
 {id:'material',name:'Material',visible:true,locked:false},
 {id:'safety',name:'Safety',visible:true,locked:false},
 {id:'annotation',name:'Text & Annotation',visible:true,locked:false}
];
let proEditor={tool:'select',activeLayer:'production',snapGrid:true,snapObjects:true,guides:true,grid:true,space:false,panning:false,panLast:null,clipboard:[],undo:[],redo:[],guides:[],selection:[],polyPoints:[],drawStart:null,drawPreview:null,initialized:false};
function proId(prefix='obj'){return prefix+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,7)}
function ensureLayoutDocument(){const m=model(),legacy=Array.isArray(m.layoutObjects)?m.layoutObjects:[];let d=m.layoutDocument;if(!d||typeof d!=='object')d={schemaVersion:PRO_LAYOUT_SCHEMA,canvas:{width:3300,height:800,widthMeters:33,heightMeters:8,unit:'m',pixelsPerUnit:100,pixelsPerMeter:100,gridMinor:.1,gridMajor:1,gridMeters:.5},layers:structuredClone(PRO_LAYER_DEFAULTS),objects:legacy,metadata:{modelName:m.name,line:m.line}};d.schemaVersion=Math.max(Number(d.schemaVersion)||0,PRO_LAYOUT_SCHEMA);d.canvas={width:3300,height:800,widthMeters:33,heightMeters:8,unit:'m',pixelsPerUnit:100,pixelsPerMeter:100,gridMinor:.1,gridMajor:1,gridMeters:.5,...d.canvas};d.layers=Array.isArray(d.layers)&&d.layers.length?d.layers:structuredClone(PRO_LAYER_DEFAULTS);d.objects=legacy;d.objects.forEach((o,i)=>{o.id=o.id||proId();o.name=o.name||o.text||o.type;o.layerId=o.layerId||proLayerForType(o.type);o.zIndex=Number.isFinite(o.zIndex)?o.zIndex:i;o.visible=o.visible!==false;o.locked=!!o.locked;o.style={fill:o.fillColor||'#ffffff',stroke:o.strokeColor||'#334155',strokeWidth:+o.strokeWidth||2,opacity:o.opacity==null?1:+o.opacity,...o.style};o.metadata={processId:o.processId||null,processName:o.processName||'',processNo:o.processNo||null,equipmentId:o.equipmentId||null,equipmentName:o.equipmentName||'',TT:o.TT||null,MP:o.MP||null,status:o.status||'',note:o.note||'',...o.metadata}});m.layoutDocument=d;m.layoutObjects=d.objects;return d}
function proLayerForType(type){if(['text','slot-number','dimension-h','dimension-v'].includes(type))return'annotation';if(['zone','wall','door','column','stairs','walkway','safety-zone'].includes(type))return type.includes('safety')||type==='walkway'?'safety':'building';if(['rack','fifo-rack','pallet','material-box','trolley','agv'].includes(type))return'material';if(['table','station','process-station'].includes(type))return'process';if(['rectangle','arrow','line','circle','triangle','block-arrow','star'].includes(type))return'production';return'equipment'}
function proPushHistory(label){const doc=ensureLayoutDocument(),json=JSON.stringify({objects:doc.objects,layers:doc.layers,canvas:doc.canvas});if(proEditor.undo.at(-1)?.json===json)return;proEditor.undo.push({label,json});if(proEditor.undo.length>80)proEditor.undo.shift();proEditor.redo=[];proRenderHistoryButtons()}
function proRestore(entry,target){if(!entry)return;const current={label:'current',json:JSON.stringify({objects:ensureLayoutDocument().objects,layers:ensureLayoutDocument().layers,canvas:ensureLayoutDocument().canvas})};target.push(current);const data=JSON.parse(entry.json),doc=ensureLayoutDocument();doc.objects=data.objects;doc.layers=data.layers;doc.canvas=data.canvas;model().layoutObjects=doc.objects;persistLocal();renderShapesCanvas();proRenderPanels();scheduleSave()}
function proUndo(){const e=proEditor.undo.pop();if(e)proRestore(e,proEditor.redo);proRenderHistoryButtons()}
function proRedo(){const e=proEditor.redo.pop();if(e)proRestore(e,proEditor.undo);proRenderHistoryButtons()}
function proRenderHistoryButtons(){const u=$('proUndo'),r=$('proRedo');if(u)u.disabled=!proEditor.undo.length;if(r)r.disabled=!proEditor.redo.length}
function proSelectedObjects(){return fabricLayoutCanvas?.getActiveObjects?.()||[]}
function proSelectedRows(){const ids=new Set(proSelectedObjects().map(o=>o.layoutId));return ensureLayoutDocument().objects.filter(o=>ids.has(o.id))}
function proCommitFabricSelection(label){const objects=proSelectedObjects();if(!objects.length)return;proPushHistory(label);objects.forEach(syncFabricObject);renderShapesCanvas();proRenderPanels()}


function proPolylinePoint(p){proEditor.polyPoints.push({x:p.x,y:p.y});if(proEditor.drawPreview)fabricLayoutCanvas.remove(proEditor.drawPreview);proEditor.drawPreview=new fabric.Polyline(proEditor.polyPoints,{fill:proEditor.tool==='polygon'?'rgba(15,118,110,.12)':'transparent',stroke:'#0f766e',strokeWidth:2,strokeDashArray:[5,4],selectable:false,evented:false,excludeFromExport:true});fabricLayoutCanvas.add(proEditor.drawPreview)}
function proFinishPolyline(){if(proEditor.polyPoints.length<2)return;const pts=proEditor.polyPoints,x=Math.min(...pts.map(p=>p.x)),y=Math.min(...pts.map(p=>p.y)),local=pts.map(p=>({x:p.x-x,y:p.y-y})),w=Math.max(12,Math.max(...local.map(p=>p.x))),h=Math.max(12,Math.max(...local.map(p=>p.y)));if(proEditor.drawPreview)fabricLayoutCanvas.remove(proEditor.drawPreview);proPushHistory('Draw '+proEditor.tool);const o=makeShape(proEditor.tool,x,y,{width:w,height:h,points:local,text:''});o.layerId=proEditor.activeLayer;o.metadata={};shapeArray().push(o);proEditor.polyPoints=[];proEditor.drawPreview=null;proEditor.selection=[o.id];persistLocal();scheduleSave();renderShapesCanvas()}

function proDrawingTool(){return['rectangle','circle','line','arrow','text','dimension-h','dimension-v','zone'].includes(proEditor.tool)}
function proDrawPreview(start,end){if(!fabricLayoutCanvas)return;const x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.max(2,Math.abs(end.x-start.x)),h=Math.max(2,Math.abs(end.y-start.y));if(proEditor.drawPreview)fabricLayoutCanvas.remove(proEditor.drawPreview);const common={left:x,top:y,fill:'rgba(15,118,110,.12)',stroke:'#0f766e',strokeWidth:1,strokeDashArray:[5,4],selectable:false,evented:false,excludeFromExport:true};proEditor.drawPreview=proEditor.tool==='circle'?new fabric.Ellipse({...common,rx:w/2,ry:h/2}):['line','arrow','dimension-h','dimension-v'].includes(proEditor.tool)?new fabric.Line([start.x,start.y,end.x,end.y],{...common,fill:null}):new fabric.Rect({...common,width:w,height:h});fabricLayoutCanvas.add(proEditor.drawPreview);fabricLayoutCanvas.requestRenderAll()}
function proFinishDrawing(end){const start=proEditor.drawStart;if(!start)return;const type=proEditor.tool,x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.max(12,Math.abs(end.x-start.x)),h=Math.max(12,Math.abs(end.y-start.y));if(proEditor.drawPreview)fabricLayoutCanvas.remove(proEditor.drawPreview);proEditor.drawStart=proEditor.drawPreview=null;proPushHistory('Draw '+type);const o=makeShape(type,x,y,{width:w,height:h,text:type==='text'?'Văn bản':type==='zone'?'KHU VỰC':type.startsWith('dimension')?((type==='dimension-h'?w:h)/ensureLayoutDocument().canvas.pixelsPerUnit).toFixed(2)+' '+ensureLayoutDocument().canvas.unit:''});o.layerId=type==='zone'?'safety':type.startsWith('dimension')||type==='text'?'annotation':proEditor.activeLayer;o.name=o.text||type;o.metadata={};shapeArray().push(o);shapeSelectedId=o.id;proEditor.selection=[o.id];persistLocal();scheduleSave();renderShapesCanvas();if(type==='text')setTimeout(()=>{const obj=fabricLayoutCanvas?.getObjects().find(x=>x.layoutId===o.id);if(obj)editFabricText(obj)},0)}

function proSetTool(tool){proEditor.tool=tool;document.querySelectorAll('[data-pro-tool]').forEach(b=>b.classList.toggle('active',b.dataset.proTool===tool));if(!fabricLayoutCanvas)return;fabricLayoutCanvas.selection=tool==='select';fabricLayoutCanvas.isDrawingMode=tool==='pen';fabricLayoutCanvas.defaultCursor=tool==='pan'?'grab':tool==='select'?'default':'crosshair';if(tool==='pen'){fabricLayoutCanvas.freeDrawingBrush=new fabric.PencilBrush(fabricLayoutCanvas);fabricLayoutCanvas.freeDrawingBrush.color=$('shapeStrokeInput').value;fabricLayoutCanvas.freeDrawingBrush.width=+$('shapeStrokeWidth').value||2}proStatus()}
function proAdd(type,metadata={},at=null){if(!canEdit())return toast('Cần quyền Admin để chỉnh sửa layout.');proPushHistory('Create '+type);addCanvasShape(type);const row=shapeArray().find(o=>o.id===shapeSelectedId);if(row){row.layerId=proEditor.activeLayer;row.metadata={...row.metadata,...metadata};row.name=row.text||type;if(at){row.x=Math.max(0,at.x-row.width/2);row.y=Math.max(0,at.y-row.height/2)}if(type==='dimension-h'){row.text='1.00 m';row.width=100;row.height=34;row.fillColor='none'}if(type==='dimension-v'){row.text='1.00 m';row.width=34;row.height=100;row.fillColor='none'}}ensureLayoutDocument();renderShapesCanvas();proRenderPanels()}
function proZoom(delta,point){if(!fabricLayoutCanvas)return;let z=fabricLayoutCanvas.getZoom();z=Math.max(.1,Math.min(5,z*delta));fabricLayoutCanvas.zoomToPoint(point||new fabric.Point(fabricLayoutCanvas.width/2,fabricLayoutCanvas.height/2),z);shapeZoom=z;proStatus()}
function proFit(selection=false){if(!fabricLayoutCanvas)return;const objects=selection?proSelectedObjects():fabricLayoutCanvas.getObjects().filter(o=>!o.excludeFromExport);if(!objects.length)return;const rect=objects.reduce((a,o)=>{const r=o.getBoundingRect();return{left:Math.min(a.left,r.left),top:Math.min(a.top,r.top),right:Math.max(a.right,r.left+r.width),bottom:Math.max(a.bottom,r.top+r.height)}},{left:Infinity,top:Infinity,right:-Infinity,bottom:-Infinity}),w=rect.right-rect.left,h=rect.bottom-rect.top,z=Math.max(.1,Math.min(5,Math.min((fabricLayoutCanvas.width-100)/w,(fabricLayoutCanvas.height-100)/h)));fabricLayoutCanvas.setViewportTransform([z,0,0,z,50-rect.left*z,50-rect.top*z]);shapeZoom=z;proStatus()}
function proResetView(){if(!fabricLayoutCanvas)return;fabricLayoutCanvas.setViewportTransform([1,0,0,1,0,0]);shapeZoom=1;proStatus()}
function proClearGuides(){if(!fabricLayoutCanvas)return;proEditor.guides.forEach(g=>fabricLayoutCanvas.remove(g));proEditor.guides=[]}
function proGuide(x1,y1,x2,y2){const l=new fabric.Line([x1,y1,x2,y2],{stroke:'#e11d48',strokeWidth:1,selectable:false,evented:false,excludeFromExport:true,strokeDashArray:[5,4]});proEditor.guides.push(l);fabricLayoutCanvas.add(l);l.bringToFront()}
function proSmartSnap(target){if(!proEditor.snapObjects||!fabricLayoutCanvas)return;proClearGuides();const t=target.getBoundingRect(),zoom=fabricLayoutCanvas.getZoom(),threshold=7/zoom,candidates=fabricLayoutCanvas.getObjects().filter(o=>o!==target&&!o.excludeFromExport&&!o.group),tx=[t.left,t.left+t.width/2,t.left+t.width],ty=[t.top,t.top+t.height/2,t.top+t.height];let bestX=null,bestY=null;for(const o of candidates){const r=o.getBoundingRect(),xs=[r.left,r.left+r.width/2,r.left+r.width],ys=[r.top,r.top+r.height/2,r.top+r.height];for(const a of tx)for(const b of xs)if(Math.abs(a-b)<threshold&&(!bestX||Math.abs(a-b)<bestX.d))bestX={d:Math.abs(a-b),delta:b-a,x:b};for(const a of ty)for(const b of ys)if(Math.abs(a-b)<threshold&&(!bestY||Math.abs(a-b)<bestY.d))bestY={d:Math.abs(a-b),delta:b-a,y:b}}if(bestX){target.left+=bestX.delta;proGuide(bestX.x,-2000,bestX.x,5000)}if(bestY){target.top+=bestY.delta;proGuide(-2000,bestY.y,7000,bestY.y)}}
function proAlign(mode){const rows=proSelectedRows();if(rows.length<2)return toast('Chọn từ 2 đối tượng.');proPushHistory('Align '+mode);const left=Math.min(...rows.map(o=>o.x)),right=Math.max(...rows.map(o=>o.x+o.width)),top=Math.min(...rows.map(o=>o.y)),bottom=Math.max(...rows.map(o=>o.y+o.height)),cx=(left+right)/2,cy=(top+bottom)/2;rows.forEach(o=>{if(mode==='left')o.x=left;if(mode==='center')o.x=cx-o.width/2;if(mode==='right')o.x=right-o.width;if(mode==='top')o.y=top;if(mode==='middle')o.y=cy-o.height/2;if(mode==='bottom')o.y=bottom-o.height;proSyncWorld(o)});renderShapesCanvas();scheduleSave()}
function proDistribute(axis){const rows=proSelectedRows().sort((a,b)=>axis==='h'?a.x-b.x:a.y-b.y);if(rows.length<3)return toast('Chọn từ 3 đối tượng.');proPushHistory('Distribute '+axis);const first=rows[0],last=rows.at(-1),span=axis==='h'?(last.x+last.width-first.x):(last.y+last.height-first.y),used=rows.reduce((n,o)=>n+(axis==='h'?o.width:o.height),0),gap=(span-used)/(rows.length-1);let pos=axis==='h'?first.x:first.y;rows.forEach(o=>{if(axis==='h')o.x=pos;else o.y=pos;pos+=(axis==='h'?o.width:o.height)+gap;proSyncWorld(o)});renderShapesCanvas();scheduleSave()}
function proSame(mode){const rows=proSelectedRows();if(rows.length<2)return toast('Chọn từ 2 đối tượng.');proPushHistory('Same '+mode);const base=rows[0];rows.slice(1).forEach(o=>{if(mode!=='height')o.width=base.width;if(mode!=='width')o.height=base.height;if(typeof proSyncWorld==='function')proSyncWorld(o)});renderShapesCanvas();scheduleSave()}
function proGroup(){const rows=proSelectedRows();if(rows.length<2)return;proPushHistory('Group');const id=proId('group');rows.forEach(o=>o.groupId=id);renderShapesCanvas();scheduleSave()}
function proUngroup(){const rows=proSelectedRows();if(!rows.length)return;proPushHistory('Ungroup');rows.forEach(o=>delete o.groupId);renderShapesCanvas();scheduleSave()}
function proCopy(cut=false){const rows=proSelectedRows();if(!rows.length)return;proEditor.clipboard=structuredClone(rows);if(cut)proDelete();else toast(`Đã sao chép ${rows.length} đối tượng`)}
function proPaste(){if(!proEditor.clipboard.length||!canEdit())return;proPushHistory('Paste');const groups=new Map(),copies=proEditor.clipboard.map(o=>{const copy=structuredClone(o);copy.id=proId();copy.x=o.x+24;copy.y=o.y+24;if(o.groupId&&!groups.has(o.groupId))groups.set(o.groupId,proId('group'));copy.groupId=o.groupId?groups.get(o.groupId):undefined;proSyncWorld(copy);return copy});shapeArray().push(...copies);proEditor.selection=copies.map(o=>o.id);renderShapesCanvas();scheduleSave();toast(`Đã dán ${copies.length} đối tượng`)}
function proDuplicate(){proCopy();proPaste()}
function proDelete(){const ids=new Set(proSelectedRows().map(o=>o.id));if(!ids.size||!canEdit())return;proPushHistory('Delete');model().layoutObjects=shapeArray().filter(o=>!ids.has(o.id));ensureLayoutDocument().objects=model().layoutObjects;renderShapesCanvas();scheduleSave()}
function proLayerVisible(id,value){const l=ensureLayoutDocument().layers.find(x=>x.id===id);if(l){l.visible=value;renderShapesCanvas();scheduleSave()}}
function proLayerLocked(id,value){const l=ensureLayoutDocument().layers.find(x=>x.id===id);if(l){l.locked=value;renderShapesCanvas();scheduleSave()}}
function proMoveLayer(id,delta){const d=ensureLayoutDocument(),i=d.layers.findIndex(l=>l.id===id),j=i+delta;if(i<0||j<0||j>=d.layers.length)return;proPushHistory('Reorder layer');d.layers.splice(j,0,d.layers.splice(i,1)[0]);proRenderLayers();renderShapesCanvas();scheduleSave()}function proRenameLayer(id){const l=ensureLayoutDocument().layers.find(x=>x.id===id),name=prompt('Tên layer:',l?.name||'')?.trim();if(name){l.name=name;proRenderLayers();scheduleSave()}}function proDeleteLayer(id){const d=ensureLayoutDocument();if(d.layers.length<=1)return toast('Cần giữ ít nhất một layer.');const fallback=d.layers.find(l=>l.id!==id);d.objects.filter(o=>o.layerId===id).forEach(o=>o.layerId=fallback.id);d.layers=d.layers.filter(l=>l.id!==id);if(proEditor.activeLayer===id)proEditor.activeLayer=fallback.id;proRenderLayers();renderShapesCanvas();scheduleSave()}
function proRenderLayers(){const box=$('proLayers');if(!box)return;const d=ensureLayoutDocument();box.innerHTML=d.layers.slice().reverse().map(l=>`<div class="pro-layer ${l.id===proEditor.activeLayer?'active':''}" data-layer="${l.id}"><button class="layer-name" type="button">${esc(l.name)}</button><label title="Hiện/ẩn"><input class="layer-visible" type="checkbox" ${l.visible?'checked':''}>V</label><label title="Khóa"><input class="layer-lock" type="checkbox" ${l.locked?'checked':''}>L</label><div class="layer-actions"><button data-layer-up title="Đưa lên">↑</button><button data-layer-down title="Đưa xuống">↓</button><button data-layer-rename title="Đổi tên">R</button><button data-layer-delete title="Xóa">×</button></div></div>`).join('');box.querySelectorAll('.pro-layer').forEach(el=>{const id=el.dataset.layer;el.querySelector('.layer-name').onclick=()=>{proEditor.activeLayer=id;proRenderLayers()};el.querySelector('.layer-visible').onchange=e=>proLayerVisible(id,e.target.checked);el.querySelector('.layer-lock').onchange=e=>proLayerLocked(id,e.target.checked);el.querySelector('[data-layer-up]').onclick=()=>proMoveLayer(id,1);el.querySelector('[data-layer-down]').onclick=()=>proMoveLayer(id,-1);el.querySelector('[data-layer-rename]').onclick=()=>proRenameLayer(id);el.querySelector('[data-layer-delete]').onclick=()=>proDeleteLayer(id)})}
function proApplyLayers(){if(!fabricLayoutCanvas)return;const d=ensureLayoutDocument(),map=new Map(d.layers.map(l=>[l.id,l]));fabricLayoutCanvas.getObjects().forEach(obj=>{const row=d.objects.find(o=>o.id===obj.layoutId),layer=map.get(row?.layerId);if(!row)return;obj.visible=row.visible!==false&&layer?.visible!==false;const locked=row.locked||layer?.locked;obj.selectable=!locked;obj.evented=!locked;obj.lockMovementX=obj.lockMovementY=obj.lockScalingX=obj.lockScalingY=obj.lockRotation=!!locked});fabricLayoutCanvas.requestRenderAll()}
function proInspector(){const rows=proSelectedRows(),box=$('proInspectorBody');if(!box)return;if(!rows.length){box.innerHTML='<div class="pro-empty">Chọn đối tượng để xem thuộc tính.</div>';return}const o=rows[0],multi=rows.length>1;box.innerHTML=`<div class="pro-inspector-title">${multi?rows.length+' đối tượng':esc(o.name||o.type)}</div><div class="pro-field-grid"><label>X<input data-pro-prop="x" type="number" value="${Math.round(o.x)}"></label><label>Y<input data-pro-prop="y" type="number" value="${Math.round(o.y)}"></label><label>W<input data-pro-prop="width" type="number" min="1" value="${Math.round(o.width)}"></label><label>H<input data-pro-prop="height" type="number" min="1" value="${Math.round(o.height)}"></label><label>Góc<input data-pro-prop="rotation" type="number" value="${Math.round(o.rotation||0)}"></label><label>Opacity<input data-pro-style="opacity" type="number" min="0" max="1" step=".1" value="${o.style?.opacity??1}"></label></div><label>Tên<input data-pro-prop="name" value="${esc(o.name||'')}"></label><label>Text<textarea data-pro-prop="text">${esc(o.text||'')}</textarea></label><div class="pro-field-grid"><label>Fill<input data-pro-style="fill" type="color" value="${/^#[0-9a-f]{6}$/i.test(o.style?.fill||'')?o.style.fill:'#ffffff'}"></label><label>Border<input data-pro-style="stroke" type="color" value="${/^#[0-9a-f]{6}$/i.test(o.style?.stroke||'')?o.style.stroke:'#334155'}"></label></div><h4>Manufacturing</h4><label>Process<select data-pro-meta="processId"><option value="">— Không liên kết —</option>${model().processes.map(p=>`<option value="${esc(p.id)}" ${o.metadata?.processId===p.id?'selected':''}>${p.stt}. ${esc(p.name)}</option>`).join('')}</select></label><div class="pro-field-grid"><label>Process No.<input data-pro-meta="processNo" value="${esc(o.metadata?.processNo??'')}"></label><label>T/T<input data-pro-meta="TT" type="number" step=".01" value="${esc(o.metadata?.TT??'')}"></label><label>MP<input data-pro-meta="MP" type="number" value="${esc(o.metadata?.MP??'')}"></label><label>Equipment<input data-pro-meta="equipmentName" value="${esc(o.metadata?.equipmentName||'')}"></label></div><label>Ghi chú<textarea data-pro-meta="note">${esc(o.metadata?.note||'')}</textarea></label>`;box.querySelectorAll('[data-pro-prop],[data-pro-style],[data-pro-meta]').forEach(input=>input.onchange=()=>{if(!canEdit())return;proPushHistory('Property change');rows.forEach(row=>{if(input.dataset.proProp){const key=input.dataset.proProp;row[key]=input.type==='number'?+input.value:input.value;if(key==='name'&&!row.text)row.text=input.value}if(input.dataset.proStyle){row.style=row.style||{};row.style[input.dataset.proStyle]=input.type==='number'?+input.value:input.value;if(input.dataset.proStyle==='fill')row.fillColor=input.value;if(input.dataset.proStyle==='stroke')row.strokeColor=input.value}if(input.dataset.proMeta){row.metadata=row.metadata||{};row.metadata[input.dataset.proMeta]=input.type==='number'&&input.value!==''?+input.value:input.value;if(input.dataset.proMeta==='processId'){const p=model().processes.find(x=>x.id===input.value);row.metadata.processName=p?.name||'';row.metadata.processNo=p?.stt||null;row.metadata.TT=stationTime(p||{});row.metadata.MP=p?.mp||0}}});renderShapesCanvas();scheduleSave()})}
function proStatus(pointer){const d=ensureLayoutDocument(),selected=proSelectedRows();if($('proStatus'))$('proStatus').innerHTML=`<span>X ${pointer?pointer.x.toFixed(0):'—'} · Y ${pointer?pointer.y.toFixed(0):'—'}</span><span>Zoom ${Math.round((fabricLayoutCanvas?.getZoom()||1)*100)}%</span><span>${selected.length} selected</span><span>Scale ${d.canvas.pixelsPerUnit} px = 1 ${d.canvas.unit}</span><span>${d.objects.length} objects</span>`}
function proRenderPanels(){proRenderLayers();proInspector();proStatus();proRenderHistoryButtons()}
function proExport(kind){if(!fabricLayoutCanvas)return;if(kind==='png'){const a=document.createElement('a');a.download=`${model().name}-${model().version}-layout.png`;a.href=fabricLayoutCanvas.toDataURL({format:'png',multiplier:2});a.click()}else{const blob=new Blob([fabricLayoutCanvas.toSVG()],{type:'image/svg+xml'}),a=document.createElement('a');a.download=`${model().name}-${model().version}-layout.svg`;a.href=URL.createObjectURL(blob);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function proContextAction(action){if(action==='copy')proCopy();if(action==='paste')proPaste();if(action==='duplicate')proDuplicate();if(action==='delete')proDelete();if(action==='group')proGroup();if(action==='ungroup')proUngroup();if(action==='lock'){proSelectedRows().forEach(o=>o.locked=!o.locked);renderShapesCanvas();scheduleSave()}if(action==='front'){proSelectedRows().forEach(o=>{const a=shapeArray(),i=a.indexOf(o);a.push(a.splice(i,1)[0])});renderShapesCanvas();scheduleSave()}if(action==='back'){proSelectedRows().slice().reverse().forEach(o=>{const a=shapeArray(),i=a.indexOf(o);a.unshift(a.splice(i,1)[0])});renderShapesCanvas();scheduleSave()}if(action==='properties')$('proInspectorBody')?.scrollIntoView({behavior:'smooth'});closeStationContextMenu()}
