proInspector=function(){const rows=proSelectedRows(),box=$('proInspectorBody');if(!box)return;if(!rows.length){legacyProInspector();return}const o=rows[0];proSyncWorld(o);const multi=rows.length>1,u=proUnit();box.innerHTML=`<div class="pro-inspector-title">${multi?rows.length+' đối tượng':esc(o.name||o.type)} <small>đơn vị ${u}</small></div><div class="pro-field-grid"><label>X (${u})<input data-world="x" type="number" step="0.01" value="${proDisplay(o.world.x)}"></label><label>Y (${u})<input data-world="y" type="number" step="0.01" value="${proDisplay(o.world.y)}"></label><label>Width (${u})<input data-world="width" type="number" min="0.01" step="0.01" value="${proDisplay(o.world.width)}"></label><label>Height (${u})<input data-world="height" type="number" min="0.01" step="0.01" value="${proDisplay(o.world.height)}"></label><label>Rotation<input data-world="rotation" type="number" value="${o.world.rotation||0}"></label><label>Opacity<input data-pro-style="opacity" type="number" min="0" max="1" step=".1" value="${o.style?.opacity??1}"></label></div><label>Tên<input data-pro-prop="name" value="${esc(o.name||'')}"></label><label>Text<textarea data-pro-prop="text">${esc(o.text||'')}</textarea></label><div class="pro-field-grid"><label>Fill<input data-pro-style="fill" type="color" value="${/^#[0-9a-f]{6}$/i.test(o.style?.fill||'')?o.style.fill:'#ffffff'}"></label><label>Border<input data-pro-style="stroke" type="color" value="${/^#[0-9a-f]{6}$/i.test(o.style?.stroke||'')?o.style.stroke:'#334155'}"></label></div><h4>Manufacturing</h4><label>Process<select data-pro-meta="processId"><option value="">— Không liên kết —</option>${model().processes.map(p=>`<option value="${esc(p.id)}" ${o.metadata?.processId===p.id?'selected':''}>${p.stt}. ${esc(p.name)}</option>`).join('')}</select></label><div class="pro-field-grid"><label>Process No.<input data-pro-meta="processNo" value="${esc(o.metadata?.processNo??'')}"></label><label>T/T<input data-pro-meta="TT" type="number" step=".01" value="${esc(o.metadata?.TT??'')}"></label><label>MP<input data-pro-meta="MP" type="number" value="${esc(o.metadata?.MP??'')}"></label><label>Equipment<input data-pro-meta="equipmentName" value="${esc(o.metadata?.equipmentName||'')}"></label></div><label>Ghi chú<textarea data-pro-meta="note">${esc(o.metadata?.note||'')}</textarea></label>`;box.querySelectorAll('[data-world]').forEach(input=>input.onchange=()=>{if(!canEdit())return;proPushHistory('Real-world geometry');rows.forEach(row=>{row.world=row.world||{};row.world[input.dataset.world]=input.dataset.world==='rotation'?+input.value:proMeters(input.value);const c=ensureLayoutDocument().canvas,p=c.pixelsPerMeter;row.x=row.world.x*p;row.y=row.world.y*p;row.width=row.world.width*p;row.height=row.world.height*p;row.rotation=row.world.rotation||0;if(row.type.startsWith('dimension'))row.text=`${(row.type==='dimension-h'?row.world.width:row.world.height).toFixed(2)} m`});renderShapesCanvas();scheduleSave()});box.querySelectorAll('[data-pro-prop],[data-pro-style],[data-pro-meta]').forEach(input=>input.onchange=()=>{if(!canEdit())return;proPushHistory('Property change');rows.forEach(row=>{if(input.dataset.proProp){row[input.dataset.proProp]=input.value;if(input.dataset.proProp==='name'&&!row.text)row.text=input.value}if(input.dataset.proStyle){row.style=row.style||{};row.style[input.dataset.proStyle]=input.type==='number'?+input.value:input.value;if(input.dataset.proStyle==='fill')row.fillColor=input.value;if(input.dataset.proStyle==='stroke')row.strokeColor=input.value}if(input.dataset.proMeta){row.metadata=row.metadata||{};row.metadata[input.dataset.proMeta]=input.type==='number'&&input.value!==''?+input.value:input.value;if(input.dataset.proMeta==='processId'){const p=model().processes.find(x=>x.id===input.value);row.metadata.processName=p?.name||'';row.metadata.processNo=p?.stt||null;row.metadata.TT=p?stationTime(p):null;row.metadata.MP=p?.mp||0}}});renderShapesCanvas();scheduleSave()})};
proStatus=function(pointer){const d=ensureLayoutDocument(),selected=proSelectedRows(),p=pointer?proWorldPoint(pointer):proCursorWorld,u=proUnit(),f=proUnitFactor();if(pointer)proCursorWorld=proWorldPoint(pointer);let geometry=p?`X ${(p.x*f).toFixed(2)} ${u} · Y ${(p.y*f).toFixed(2)} ${u}`:'X — · Y —';if(selected.length===1){proSyncWorld(selected[0]);const w=selected[0].world;geometry=`X ${(w.x*f).toFixed(2)} ${u} · Y ${(w.y*f).toFixed(2)} ${u} · W ${(w.width*f).toFixed(2)} ${u} · H ${(w.height*f).toFixed(2)} ${u}`}if($('proStatus'))$('proStatus').innerHTML=`<span>${geometry}</span><span>${selected.length} selected</span><span>Scale ${d.canvas.pixelsPerMeter} px = 1 m</span><span class="status-zoom"><button id="statusZoomOut">−</button><b>${Math.round((fabricLayoutCanvas?.getZoom()||1)*100)}%</b><button id="statusZoomIn">＋</button></span>`;if($('statusZoomOut'))$('statusZoomOut').onclick=()=>proZoom(.9);if($('statusZoomIn'))$('statusZoomIn').onclick=()=>proZoom(1.1)};
const legacyProExport=proExport;
proExport=function(kind){if(kind!=='svg')return legacyProExport(kind);if(!fabricLayoutCanvas)return;const c=ensureLayoutDocument().canvas,metadata=JSON.stringify({schemaVersion:REAL_LAYOUT_SCHEMA,widthMeters:c.widthMeters,heightMeters:c.heightMeters,unit:'m',pixelsPerMeter:c.pixelsPerMeter,model:model().name,version:model().version}).replaceAll('&','&amp;').replaceAll('<','&lt;');let svg=fabricLayoutCanvas.toSVG();svg=svg.replace('<svg ',`<svg data-width-m="${c.widthMeters}" data-height-m="${c.heightMeters}" `).replace('>','><metadata>'+metadata+'</metadata>');const blob=new Blob([svg],{type:'image/svg+xml'}),a=document.createElement('a');a.download=`${model().name}-${model().version}-layout.svg`;a.href=URL.createObjectURL(blob);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
const legacyProCreateShell=proCreateShell;
proCreateShell=function(){legacyProCreateShell();const host=document.querySelector('.pro-canvas-host');host.insertAdjacentHTML('afterbegin','<canvas id="proRulerH" class="pro-ruler-h"></canvas><canvas id="proRulerV" class="pro-ruler-v"></canvas><div id="proQuickMeasure" class="pro-quick-measure" hidden></div>');const fileGroup=document.querySelector('.pro-toolbar>div');fileGroup.insertAdjacentHTML('beforeend','<button id="proAreaSetup">Area Setup</button>');const viewGroup=document.querySelector('.pro-toolbar>div:last-child');viewGroup.insertAdjacentHTML('beforeend','<button id="proMeasure" data-pro-tool="measure">Measure</button>');document.body.insertAdjacentHTML('beforeend',`<dialog id="areaSetupDialog" class="area-setup-dialog"><form id="areaSetupForm"><h2>Layout · Page / Area Setup</h2><div class="pro-field-grid"><label>Layout Width (m)<input id="areaWidth" type="number" min="1" step=".1"></label><label>Layout Height (m)<input id="areaHeight" type="number" min="1" step=".1"></label><label>Unit<select id="areaUnit"><option value="m">m</option><option value="cm">cm</option><option value="mm">mm</option></select></label><label>Grid<select id="areaGrid"><option value="0.1">0.1 m</option><option value="0.25">0.25 m</option><option value="0.5">0.5 m</option><option value="1">1 m</option></select></label><label>Orientation<select id="areaOrientation"><option value="horizontal">Horizontal</option><option value="vertical">Vertical</option></select></label></div><div class="dialog-actions"><button id="areaCancel" type="button" class="btn">Hủy</button><button type="submit" class="btn primary">Áp dụng</button></div></form></dialog>`);$('proAreaSetup').onclick=proOpenAreaSetup;$('areaSetupForm').onsubmit=proSaveAreaSetup;$('areaCancel').onclick=()=>$('areaSetupDialog').close();$('proMeasure').onclick=()=>{proSetTool('measure');proMeasurePoints=[];if(proMeasurePreview){fabricLayoutCanvas?.remove(proMeasurePreview);proMeasurePreview=null}toast('Measure: chọn điểm A và điểm B.')}};
const legacyProBindCanvas=proBindCanvas;
proBindCanvas=function(){legacyProBindCanvas();if(!fabricLayoutCanvas)return;const scroll=document.querySelector('.shapes-canvas-scroll');scroll?.addEventListener('scroll',proRenderRulers,{passive:true});fabricLayoutCanvas.on('mouse:wheel',proRenderRulers);fabricLayoutCanvas.on('mouse:move',opt=>{if(opt.target&&(opt.e.buttons===1||opt.target.__corner))proQuickMeasure(opt.target)});fabricLayoutCanvas.on('object:scaling',e=>proQuickMeasure(e.target));fabricLayoutCanvas.on('object:rotating',e=>proQuickMeasure(e.target));fabricLayoutCanvas.on('mouse:up',proHideQuickMeasure);fabricLayoutCanvas.on('mouse:down',opt=>{if(proEditor.tool==='measure'){opt.e.preventDefault();proMeasureClick(fabricLayoutCanvas.getScenePoint(opt.e))}});fabricLayoutCanvas.on('object:moving',e=>{if(proEditor.snapGrid&&ensureLayoutDocument().canvas.gridMeters>0){const g=proGridPixels();e.target.set({left:Math.round(e.target.left/g)*g,top:Math.round(e.target.top/g)*g});if(proEditor.snapObjects)proSmartSnap(e.target)}});proRenderRulers()};
const legacySetTool=proSetTool;
proSetTool=function(tool){legacySetTool(tool);if(tool==='measure'&&fabricLayoutCanvas){fabricLayoutCanvas.selection=false;fabricLayoutCanvas.defaultCursor='crosshair'}};
window.addEventListener('resize',()=>requestAnimationFrame(proRenderRulers));
